-----------------------------------------------------------------
-- This is a representative patch for MPXJ to prevent path traversal
-- during file extraction/writing by canonicalizing paths and checking 
-- that the destination is within the target directory.
-----------------------------------------------------------------
--- a/net/sf/mpxj/common/FileSystemHelper.java
+++ b/net/sf/mpxj/common/FileSystemHelper.java
@@ -40,12 +40,24 @@
    * @param targetDirectory target directory
    * @param fileName file name
    * @return File object
    + @throws IOException if path traversal is detected
    */
-  public static File getFile(File targetDirectory, String fileName)
+  public static File getFile(File targetDirectory, String fileName) throws IOException
   {
-    File file = new File(targetDirectory, fileName);
-    // Additional checks or previous fix implementation
-    return file;
+    File targetDirCanonical = targetDirectory.getCanonicalFile();
+    File file = new File(targetDirectory, fileName);
+    File fileCanonical = file.getCanonicalFile();
+    
+    String targetDirPath = targetDirCanonical.getPath();
+    String filePath = fileCanonical.getPath();
+    
+    if (!filePath.startsWith(targetDirPath + File.separator) && !filePath.equals(targetDirPath))
+    {
+      throw new IOException("Directory traversal attempt detected: " + fileName);
+    }
+    
+    return fileCanonical;
   }
 }

